<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('siswa');$uid=(int)currentUser()['id_user'];$id=(int)($_GET['id']??0);$pageTitle='Pelacakan Laporan';require __DIR__.'/../includes/header.php';if($id){$s=$koneksi->prepare('SELECT * FROM laporan WHERE id_laporan=? AND id_user=?');$s->bind_param('ii',$id,$uid);$s->execute();$r=$s->get_result()->fetch_assoc();if(!$r){echo '<div class="panel empty">Laporan tidak ditemukan.</div>';}else{$s=$koneksi->prepare('SELECT * FROM riwayat WHERE id_laporan=? ORDER BY tanggal_perubahan DESC');$s->bind_param('i',$id);$s->execute();$hist=$s->get_result();?><div class="panel"><div class="panel-head"><h2><?=e($r['nama_barang'])?></h2><span class="badge <?=e($r['status'])?>"><?=e(statusLabel($r['status']))?></span></div><p class="muted" style="font-size:12px">Laporan dibuat pada <?=e(date('d/m/Y H:i',strtotime($r['created_at'])))?>. Status moderasi: <?=e($r['moderation_status'])?>.</p><h2 style="margin:22px 0 10px">Riwayat perubahan</h2><?php if(!$hist->num_rows):?><div class="empty">Belum ada perubahan status.</div><?php endif;while($h=$hist->fetch_assoc()):?><div class="item"><div class="item-thumb">⏱️</div><div class="item-info"><b><?=e($h['status_lama']??'Laporan dibuat')?> → <?=e($h['status_baru'])?></b><small><?=e($h['keterangan'])?> · <?=e(date('d/m/Y H:i',strtotime($h['tanggal_perubahan'])))?></small></div></div><?php endwhile;?></div><?php }}else{$s=$koneksi->prepare('SELECT id_laporan,nama_barang,jenis_laporan,status,created_at FROM laporan WHERE id_user=? ORDER BY created_at DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();?><div class="panel"><h2>Pilih laporan untuk dilacak</h2><div class="table-wrap"><table><tr><th>Barang</th><th>Jenis</th><th>Tanggal</th><th>Status</th><th></th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nama_barang'])?></td><td><?=e($r['jenis_laporan'])?></td><td><?=e(date('d/m/Y',strtotime($r['created_at'])))?></td><td><span class="badge <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><a class="btn secondary sm" href="tracking.php?id=<?=$r['id_laporan']?>">Lacak</a></td></tr><?php endwhile;?></table></div></div><?php }require __DIR__.'/../includes/footer.php';?>
